@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + energyClass : string
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + isPublic : boolean
}

class TextualEntry extends AdditionalEntry {}

class NumericalEntry extends AdditionalEntry {
  + value : float
  + unit : string
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + email : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building : provides catalog of
Building "1" *-- "*" AdditionalEntry : has
Building "1" *-- "*" Image : has
Building "1" -- "0..1" Image : profile photo
Building "1" -- "*" Comment : has
User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
WebPortal "1" -- "*" User : has

@enduml

